const tenses=[["present","Présent"],["passeCompose","Passé composé"],["imparfait","Imparfait"],["futurSimple","Futur simple"],["conditionnel","Conditionnel présent"]];
const endings=["ais","ais","ait","ions","iez","aient"];
function erPresent(v){let stem=v.slice(0,-2),f=[stem+"e",stem+"es",stem+"e",stem+"ons",stem+"ez",stem+"ent"];if(v.endsWith("ger"))f[3]=stem+"eons";if(v.endsWith("cer"))f[3]=stem.slice(0,-1)+"çons";if(v.endsWith("yer")){let y=stem.slice(0,-1)+"i";f[0]=y+"e";f[1]=y+"es";f[2]=y+"e";f[5]=y+"ent"}if(/(?:appeler|rappeler|jeter|rejeter|projeter|feuilleter|épeler)$/.test(v)){let x=stem+stem.slice(-1);f=[x+"e",x+"es",x+"e",stem+"ons",stem+"ez",x+"ent"]}else if(/(?:acheter|racheter|geler|congeler|peler|celer|modeler|harceler|marteler|ciseler|démanteler)$/.test(v)){let x=stem.replace(/e(?=[^e]*$)/,"è");f=[x+"e",x+"es",x+"e",stem+"ons",stem+"ez",x+"ent"]}else if(/(?:lever|mener|peser|semer|promener|emmener|amener|enlever|élever|espérer|préférer|répéter|compléter|céder|considérer)$/.test(v)){let x=stem.replace(/é(?=[^é]*$)/,"è").replace(/e(?=[^e]*$)/,"è");f=[x+"e",x+"es",x+"e",stem+"ons",stem+"ez",x+"ent"]}return f;}
function formsFor(v){const saved=irregularForms[v];if(saved)return {present:saved["présent"],passeCompose:saved["passé composé"],imparfait:saved.imparfait,futurSimple:saved["futur simple"],conditionnel:saved.conditionnel};const isEr=v.endsWith("er"),stem=v.slice(0,-2);const present=isEr?erPresent(v):[stem+"is",stem+"is",stem+"it",stem+"issons",stem+"issez",stem+"issent"];const nousStem=v.endsWith("cer")?stem:present[3].slice(0,-3);const imparfait=endings.map(x=>nousStem+x);const futureStem=({"envoyer":"enverr","renvoyer":"renverr","payer":"payer","appeler":"appeller","rappeler":"rappeller","jeter":"jetter","rejeter":"rejetter","acheter":"achèter","racheter":"rachèter","lever":"lèver","mener":"mèner","peser":"pèser","promener":"promèner","emmener":"emmèner","amener":"amèner","enlever":"enlèver","élever":"élèver","espérer":"espérer","préférer":"préférer"})[v]||v;const future=["ai","as","a","ons","ez","ont"].map(x=>futureStem+x);const conditional=endings.map(x=>futureStem+x);const pp=isEr?stem+"é":stem+"i";const aux=["ai","as","a","avons","avez","ont"];const passeCompose=aux.map(x=>x+" "+pp);return {present,passeCompose,imparfait,futurSimple:future,conditionnel:conditional};}
